"""Copernicus DSM source tiles; committed numeric subset is generated by S2."""
import gzip
import json
import math

import rasterio

from pipeline.common import CONFIG, RAW, SEED, dump, fetch, gzip_json, source


def run():
    downloads = []
    for lat, lon in CONFIG["dem"]["tiles"]:
        name = f"Copernicus_DSM_COG_10_{'N' if lat >= 0 else 'S'}{abs(lat):02d}_00_{'E' if lon >= 0 else 'W'}{abs(lon):03d}_00_DEM"
        path, meta = fetch(f"https://copernicus-dem-30m.s3.amazonaws.com/{name}/{name}.tif", name + ".tif")
        downloads.append({**meta, "raw_path": str(path), "tile": name})
    first = downloads[0]
    s = source("copernicus_dem", "Copernicus DEM GLO-30 Public (2021 release)", "https://registry.opendata.aws/copernicus-dem/",
               "Copernicus DEM Licence (free public use with attribution)",
               "Copernicus Digital Elevation Model © DLR e.V. 2010–2014 and © Airbus Defence and Space GmbH 2014–2018, provided under COPERNICUS by the European Union and ESA; accessed 2026-10-26",
               "2021-01-01T00:00:00Z", first["retrieved_at"],
               "DSM includes canopy and infrastructure; not a bare-earth DTM. 2021 is release year, not observation time of every pixel.")
    dump(RAW / "dem_stage.json", {"source": s, "downloads": downloads})
    graph_path = SEED / "walk_graph.json.gz"
    if graph_path.exists():
        with gzip.open(graph_path, "rt") as f:
            graph = json.load(f)
        sampled = 0
        for tile in downloads:
            with rasterio.open(tile["raw_path"]) as dem:
                b = dem.bounds
                nodes = [n for n in graph["nodes"] if b.left <= n["lon"] < b.right and b.bottom < n["lat"] <= b.top]
                for node, value in zip(nodes, dem.sample([(n["lon"], n["lat"]) for n in nodes], masked=True)):
                    z = value[0]
                    if not getattr(z, "mask", False) and math.isfinite(float(z)):
                        node["elevation_m"] = round(float(z), 2)
                        node["elevation_source"] = "copernicus_dem"
                        sampled += 1
        gzip_json(graph_path, graph)
        print(f"Walk graph elevations: {sampled}/{len(graph['nodes'])}", flush=True)
    print("\n".join(d["raw_path"] for d in downloads), flush=True)


if __name__ == "__main__":
    run()
